import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {flow,earnOpening}from './opening-flow.mjs';import {findPath}from '../navigation.js';import {STRING_HZ,ROOM_SOUND}from '../instrument.js';
const source=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
test('the early workshop patrol cannot repeatedly trap an ungeared player in warning dialogues',()=>{const h=flow(),w=h.w;h.use(w.objects().find(o=>o.type==='npc'));h.use(w.objects().find(o=>o.type==='portal'));h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===0));h.choose();h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===1));h.choose();h.choose();h.use(w.objects().find(o=>o.type==='portal'&&o.to==='workshop'));assert.equal(w.scene.key,'workshop');assert.equal(w.state.story.weapon,false);for(let i=0;i<100;i++){assert.equal(w.objects().some(o=>o.type==='patrol'),false);assert.equal(w.state.mode,'field');}h.use(w.objects().find(o=>o.type==='cache'&&o.bit===1));h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===3));h.choose();assert.ok(w.objects().some(o=>o.type==='patrol'));});
test('every chapter has an actual connected optional interior, three reachable hiding places and a return route',()=>{const {w}=earnOpening();assert.equal(w.data.scenes.filter(s=>!s.biome&&!s.originId).length,source.scenes.length+24);assert.equal(w.data.scenes.flatMap(r=>r.objects).filter(o=>o.type==='secret').length,72);for(const m of w.data.campaign.missions){const room=w.data.scenes.find(r=>r.location===700+m.id);assert.ok(room.title&&room.interior&&room.household.furnishings.length);const anchor=w.data.scenes.find(r=>r.chapter===m.id&&r.objects.some(o=>o.to===room.key));assert.ok(anchor);const d=anchor.objects.find(o=>o.to===room.key);assert.ok(findPath(anchor,anchor.arrive,d.xy,1).length);assert.equal(room.doors[0].to,anchor.key);assert.equal(anchor.floor[d.xy[1]][d.xy[0]],'.');for(const o of room.objects){assert.ok(Math.hypot(room.arrive[0]-o.xy[0],room.arrive[1]-o.xy[1])<=1||findPath(room,room.arrive,o.xy,1).length,`${m.id} ${o.type}`);}for(const s of anchor.objects.filter(o=>o.type==='secret'))assert.ok(findPath(anchor,anchor.arrive,s.xy,1).length);}});
test('wrong latch guesses cost nothing; successful clues unlock a once-only reward preserved through saves',()=>{const h=earnOpening(),w=h.w;w.loadScene(701);h.finish();let r=w.scene.objects.find(o=>o.type==='riddle'),s=w.scene.objects.find(o=>o.lock);w.state.x=r.xy[0]+.5;w.state.y=r.xy[1]+.5;const items={...w.state.items};h.use(r);h.choose(0);assert.deepEqual(w.state.items,items);assert.equal(w.state.exploration.solved.length,0);h.use(r);h.choose(1);h.use(s);const gold=w.state.gold;assert.equal(w.state.exploration.relics.length,1);w.restore(w.save());assert.equal(w.state.exploration.relics.length,1);h.use(s);assert.equal(w.state.gold,gold);});
test('hidden cache hints appear at close range and never masquerade as a mandatory campaign objective',()=>{const h=earnOpening(),w=h.w;w.loadScene(701);h.finish();const s=w.scene.objects.find(o=>o.type==='secret');assert.equal(w.objects().includes(s),false);w.state.x=s.xy[0]+.5;w.state.y=s.xy[1]+1.5;assert.ok(w.objects().includes(s));assert.equal(s.bit,undefined);const flags=JSON.stringify(w.state.flags);h.use(s);assert.equal(JSON.stringify(w.state.flags),flags);});
test('legacy saves receive optional rooms without losing their kit or gaining rewards',()=>{const h=earnOpening(),s=JSON.parse(h.w.save());delete s.story;delete s.exploration;h.w.restore(s);assert.equal(h.w.scenes.has(724),true);assert.equal(h.w.state.gold,s.gold);assert.deepEqual(h.w.state.party,s.party);});
test('instrument tuning matches the recovered solver and uses bounded low-cost room parameters',()=>{const tuning=JSON.parse(fs.readFileSync(new URL('../instrument-tuning.json',import.meta.url)));assert.deepEqual(STRING_HZ,tuning.strings.map(s=>s.target_Hz));for(const r of Object.values(ROOM_SOUND)){assert.ok(r.wet>0&&r.wet<.3);assert.ok(r.q<30);assert.ok(r.delay*1.9<.2);}assert.ok(tuning.calibration.normal_equation_residual<1e-8);});
